033 ▓ Αυτοματισμός για Μπάρες του ΟΣΕ - Χρήση Arduino

Δεν το βλέπετε; 30 χρόνια και απο κούκου τίποτα. ΔΕΝ ΜΠΟΡΟΥΝ! Μόνο κομπίνες κάνουν. Χρειάζονται όμως και οι γραφικοί, για τα προσχήματα.

@followers @highlight 

Ας σχεδιάσουμε ένα κύκλωμα - καινοτομία για να κατεβαίνουν και να ανεβαίνουν AYTOMATA οι ηλεκτρικά κινούμενες μπάρες στον ΟΣΕ. Δέκα λεπτάκια είναι. ΔΕΝ ΜΠΟΡΕΣΑΝ. 

Xρειάζονται δύο sensors στις θέσεις 3 και 4, λιγο πρίν και λιγο μετά τις μπάρες. Και δύο σήματα συνεχώς εκπεμπόμενα απο το πρώτο και τελευταίο βαγόνι (1, 2).

* Για τις Χειροκίνητες να πάει ο Καραμανλής που ξέρει.

Το κόστος για αυτο το κύκλωμα το υπολογίζουμε στα 2 εκ. ευρώ. 1 εκ. ευρώ ο ΟΣΕ και 1 εκ. ευρω η Hellenic Train.

Να τους δώσετε και τον κώδικα για το Arduino. Να μη κουρασθούν. Στην Ελλάδα μόνο ο Μητσοτάκης πληρώνεται... Για μένα πληρωμή να είναι η προτομή μου στην Προεδρία της Δημοκρατίας του Μπανανιστάν.

▓ Βασικό κύκλωμα

cpp
const int sensorC = 2; // Αισθητήρας C
const int sensorD = 3; // Αισθητήρας D
const int switchPin = 4; // Διακόπτης (UP = HIGH, DOWN = LOW)
const int outputUp = 9; // Σήμα UP για μπάρες
const int outputDown = 10; // Σήμα DOWN για μπάρες

void setup() {
 pinMode(sensorC, INPUT);
 pinMode(sensorD, INPUT);
 pinMode(switchPin, INPUT);
 pinMode(outputUp, OUTPUT);
 pinMode(outputDown, OUTPUT);
 digitalWrite(outputUp, LOW);
 digitalWrite(outputDown, LOW);
}

void loop() {
 int cState = digitalRead(sensorC);
 int dState = digitalRead(sensorD);
 int switchState = digitalRead(switchPin);

 // Αυτόματη Λειτουργία (προτεραιότητα)
 if (cState == HIGH && dState == LOW) {
 digitalWrite(outputDown, HIGH); // Μπάρες Κάτω
 digitalWrite(outputUp, LOW);
 } else if (cState == LOW && dState == HIGH) {
 delay(5000); // Καθυστέρηση 5 δευτερολέπτα
 digitalWrite(outputUp, HIGH); // Μπάρες Πάνω
 digitalWrite(outputDown, LOW);
 } else {
 // Χειροκίνητη Λειτουργία (μόνο αν αισθητήρες off)
 if (switchState == HIGH) {
 digitalWrite(outputUp, HIGH); // Διακόπτης UP
 digitalWrite(outputDown, LOW);
 } else if (switchState == LOW) {
 digitalWrite(outputDown, HIGH); // Διακόπτης DOWN
 digitalWrite(outputUp, LOW);
 } else {
 digitalWrite(outputUp, LOW); // Καμία ενέργεια
 digitalWrite(outputDown, LOW);
 }
 }
}

